import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>إنشاء favicon يبدو تقنيًا، لكن مع الأداة المناسبة يستغرق بضع دقائق فقط. ترفع شعارًا وتضبط حفنة خيارات وتنزّل حزمة ملفات وتضيف مقتطفًا قصيرًا إلى موقعك. يغطي هذا الدليل العملية كاملة.</p>\n<p>قبل أن تبدأ تحتاج شيئين فقط: ملف شعار والوصول إلى ملفات موقعك. شعار مربع بصيغة PNG أو SVG يعمل أفضل، والنسخة الأكبر لديك تعطي أنقى نتيجة. وإذا كان لديك JPG فقط، فهو يعمل أيضًا، لكنك تفقد خيار الشفافية.</p>\n<p>يقوم <a href=\"/ar/munshi-favicon/\">مولد favicon</a> بكل العمل في متصفحك. شعارك لا يغادر جهازك أبدًا، ولا حساب للإنشاء، والحزمة المنتهية تُنزّل كـZIP. اتبع الخطوات أدناه وسيكون لموقعك مجموعة أيقونات كاملة.</p>\n<h2 id=\"step-1-prepare-your-logo\">الخطوة 1: جهّز شعارك</h2>\n<p>افتح ملف شعارك وتحقق من أنه مربع أو شبه مربع: لوحة مربعة تستفيد أفضل من مساحة favicon الصغيرة، بينما شعار مستطيل عريض يترك أشرطة فارغة حوله.</p>\n<p>راجع الدقة: صورة مصدر 512 في 512 بكسلًا أو أكثر تصغّر دون مشاكل إلى كل أحجام favicon. صورة 64 بكسلًا ممدودة إلى 512 لـAndroid تبدو ناعمة، فابدأ من أكبر مصدر لديك. وبسّط التصميم إن كان به نص صغير أو تفاصيل دقيقة: شعار تحت الشعار لا ينجو عند 16 بكسلًا، فأزله لنسخة favicon. واحتفظ بأقوى عنصر: الشكل أو الحرف الذي يعرّف علامتك.</p>\n<p>وإذا كان لشعارك خلفية شفافة، اتركها هكذا الآن: الشفافية تمنحك خيارات أكثر في المولد، لأنك تستطيع إضافة لون خلفية لاحقًا إن أظهرت المعاينات أنك تحتاجه.</p>\n<h2 id=\"step-2-upload-to-the-generator\">الخطوة 2: ارفع الشعار إلى المولد</h2>\n<p>افتح <a href=\"/ar/munshi-favicon/\">مولد favicon</a> واسحب شعارك إلى منطقة الرفع، أو انقر لاختيار الملف من جهازك. ويمكنك أيضًا لصق صورة منسوخة مباشرة من الحافظة بـCtrl+V.</p>\n<p>تقبل الأداة ملفات PNG وSVG وJPG وWebP وHEIC حتى 20 MB: معظم الشعارات أصغر بكثير من ذلك الحد، فالحجم نادرًا ما يكون مشكلة. وإذا كان ملفك صورة هاتف HEIC، فسيعمل أيضًا. وبمجرد تحميل الملف، يبني المولد معاينة لحزمة الأيقونات: سترى العلامة مرسومة بأحجام عدة، فتستطيع الحكم على قراءتها صغيرة وكبيرة. وإذا بدا الشعار صغيرًا جدًا، أعد تحضير نسخة مربعة أكثر.</p>\n<p>وإذا رفعت شعارًا مستطيلًا، تضبطه الأداة داخل اللوحة المربعة دون تمديده: راجع إن بدت النتيجة صغيرة جدًا. وإذا كان الأمر كذلك، عُد وجهّز نسخة مربعة أكثر من علامتك.</p>\n<h2 id=\"step-3-set-padding-and-shape\">الخطوة 3: اضبط الحشو والشكل</h2>\n<p>الحشو هو المساحة بين شعارك وحافة الأيقونة: ابدأ بكمية صغيرة، كافية لئلا يلمس الشعار حافة اللوحة. شعار ملتصق بالحافة يبدو ضيقًا، خصوصًا في الأحجام الصغيرة.</p>\n<p>زد الحشو إذا كان للشعار حواف رفيعة أو ضربات دقيقة: التفاصيل الدقيقة تحتاج هواءً وإلا اندمجت مع الحافة في الأحجام الصغيرة. وقلّله إذا كانت العلامة قوية وبسيطة، لأن حشوًا كبيرًا يجعل علامة جريئة تبدو صغيرة. ونصف قطر الزاوية يدوّر زوايا خلفية الأيقونة: تدوير خفيف ينعّم المظهر دون تغيير طابع العلامة. وتدوير كامل يحوّل الأيقونة إلى دائرة، وهو ما يناسب بعض العلامات لكنه يقطع زوايا شعار مربع.</p>\n<p>راقب المعاينات وأنت تضبط هذه الضوابط: تُطبق التغييرات على كل أحجام الحزمة دفعة واحدة، فضبط واحد يحدّث معًا أيقونة التبويب وأيقونة Apple وأيقونات Android.</p>\n<h2 id=\"step-4-choose-a-background-fill\">الخطوة 4: اختر لون خلفية</h2>\n<p>لون الخلفية هو ما خلف شعار شفاف: تركه شفافًا يبقي الأيقونة خفيفة ويترك لون تبويب المتصفح ظاهرًا. يعمل هذا جيدًا للشعارات الداكنة والجريئة على تبويبات فاتحة.</p>\n<p>أضف تعبئة صلبة عندما يكون الشعار باهتًا أو رفيعًا أو فاتح اللون: مربع أبيض أو بلون علامتك خلف التصميم يمنحه تباينًا في أي تبويب. اختر تعبئة تكمل علامتك، لا تنافسها. وتتجاهل Apple Touch Icons الشفافية وتملأ المناطق الفارغة بالأسود، فتعبئة صلبة هي الخيار الآمن لأيقونة الشاشة الرئيسية. وإذا بقي favicon التبويب شفافًا، فسيكون أيقونة Apple مختلفة، وهذا مقبول طالما بدا الاثنان جيدين.</p>\n<p>راجع التعبئة في معاينات التبويب الفاتح والداكن: تعبئة تبدو رائعة في تبويب فاتح قد تبدو ثقيلة في تبويب داكن، والعكس. والتعبئة المناسبة تبقي العلامة مقروءة في الاثنين.</p>\n<h2 id=\"step-5-check-the-previews\">الخطوة 5: راجع المعاينات</h2>\n<p>يُظهر المولد أيقونتك في تبويبات متصفح فاتحة وداكنة: انظر أولًا إلى العرض الداكن إن كان شعارك داكنًا، والفاتح إن كان شعارك فاتحًا. والمعاينة التي يطابق فيها لون شعارك لون التبويب هي حيث يختفي الأيقونة.</p>\n<p>انتبه خصوصًا لأصغر معاينة، أيقونة التبويب 16 بكسلًا: إنه الحجم الذي يراه الزوار غالبًا وحيث يموت التفصيل. وإذا ما زلت تميز العلامة هناك، فستعمل في كل مكان. وألقِ نظرة أيضًا على أكبر معاينة، أيقونة Android 512 بكسلًا: علامة تُقرأ جيدًا صغيرة قد تبدو فارغة أو ضائعة بحجم كبير، خصوصًا إذا كانت حرفًا واحدًا.</p>\n<p>لا تتخطَّ هذه الخطوة: تكتشف المعاينة أكثر فشلين شيوعًا: أيقونة تختفي في الوضع الداكن وعلامة تصبح عجينة بحجم التبويب. وإصلاحهما الآن يستغرق ثوانٍ.</p>\n<h2 id=\"step-6-download-the-pack\">الخطوة 6: نزّل الحزمة</h2>\n<p>عندما تبدو المعاينات جيدة، نزّل ZIP: ستجد بداخله favicon.ico وApple Touch Icon وأيقونتي Android 192 و512 بكسلًا وملف site.webmanifest ومقتطف HTML.</p>\n<p>ويمكنك أيضًا تنزيل ملفات منفردة إذا احتجت واحدًا منها فقط: أخذ favicon.ico وحده يكفي لإصلاح سريع في موقع قديم، بينما ZIP الكامل هو المناسب لموقع جديد. وفك ضغط الحزمة على حاسوبك وانظر إلى الملفات قبل رفعها: تحقق من أن أحجام الأيقونات موجودة وأن ملف البيان مضمن. نظرة سريعة الآن تمنع رفعًا ناقصًا.</p>\n<p>واحتفظ بنسخة من ZIP في مكان آمن: إذا غيّرت علامتك أو فقدت ملفات الموقع لاحقًا، فـZIP هو أسرع طريقة لاستعادة مجموعة الأيقونات. وينفع أيضًا لتسجيل ما نشرت بالضبط.</p>\n<h2 id=\"step-7-upload-the-files\">الخطوة 7: ارفع الملفات</h2>\n<p>ارفع ملفات الأيقونات إلى مجلد جذر موقعك، نفس المجلد الذي فيه صفحتك الرئيسية: تبحث المتصفحات عن favicon.ico في الجذر افتراضيًا، فوضعها هناك يغطي معظم الحالات.</p>\n<p>استخدم مدير ملفات استضافتك أو عميل FTP أو أداة النشر لنسخ الملفات: الملفات صغيرة، فالرفع يستغرق ثوانٍ. وتأكد من أن كل ملف رُفع: ملف مفقود واحد يعني أيقونة مفقودة في مكان ما. وإذا لم يُظهر منشئ موقعك مجلد الجذر، ابحث عن خيار favicon أو أيقونة موقع في لوحته: كثير من المنشئين يقبل أيقونة مرفوعة ويتولون وضعها بأنفسهم.</p>\n<p>لا تغيّر أسماء الملفات إلا إذا حدّثت مقتطف HTML أيضًا: ملف معاد تسميته بمسار قديم في المقتطف هو نفسه ملف مفقود، وسيعرض المتصفح أيقونة افتراضية.</p>\n<h2 id=\"step-8-add-the-html-snippet\">الخطوة 8: أضف مقتطف HTML</h2>\n<p>افتح مقتطف HTML الذي جاء مع الحزمة: يحتوي وسوم ارتباط لـfavicon وApple Touch Icon وبيان الويب. انسخ الكتلة كلها كما جاءت، دون تعديل المسارات.</p>\n<p>الصق المقتطف داخل قسم head في صفحاتك، قرب وسوم meta والارتباط الأخرى: في موقع HTML بسيط، أضفه إلى كل صفحة أو إلى قالب ترويسة مشترك. واحفظ الملف وأعد تحميل موقعك في المتصفح: يجب أن يتغير أيقونة التبويب إلى favicon الجديد. وإذا لم يتغير، فقد يكون الأيقونة القديم في ذاكرة التخزين المؤقت، وهو أمر طبيعي يُغطى في الخطوة التالية.</p>\n<p>راجع مسارات المقتطف إذا بقي الأيقونة غير ظاهر بعد مسح ذاكرة التخزين المؤقت: مسار يشير إلى مجلد فرعي غير موجود هو السبب المعتاد. ويفترض المقتطف أن الملفات في الجذر.</p>\n<h2 id=\"step-9-clear-the-cache-and-test\">الخطوة 9: امسح ذاكرة التخزين المؤقت واختبر</h2>\n<p>تخزّن المتصفحات favicon في ذاكرة التخزين المؤقت لمدة طويلة، فمتصفحك قد يستمر في عرض الأيقونة القديم بعد الرفع: قم بتحديث قسري بـCtrl+Shift+R لطلب نسخة جديدة.</p>\n<p>اختبر الأيقونة في متصفح ثانٍ أو نافذة خاصة، حيث ذاكرة التخزين المؤقت فارغة: نافذة خاصة تُظهر ما يراه زائر جديد، وهو الاختبار الصادق. وإذا ظهر الأيقونة هناك، فالرفع نجح ومتصفحك الرئيسي فقط يحتاج وقتًا. وأضف الموقع إلى الشاشة الرئيسية لهاتفك وراجع أيقونة Apple أو Android: أيقونة الشاشة الرئيسية هي النسخة الأكبر، فتُظهر عيوبًا تخفيها معاينة التبويب.</p>\n<p>واحفظ الصفحة في الإشارات المرجعية وانظر إلى القائمة: يجب أن يظهر favicon بجانب العنوان المحفوظ. أيقونة مفقود في الإشارات المرجعية غالبًا يعني أن مسار المقتطف خطأ أو أن الملف لم يُرفع.</p>\n<h2 id=\"step-10-when-to-regenerate\">الخطوة 10: متى تعيد التوليد</h2>\n<p>أعد توليد الحزمة كلما تغيّر شعارك، ولو قليلًا: شعار جديد أو لون علامة جديد أو رمز مكرر يستحق حزمة جديدة، لأن favicon قديم يناقض علامتك الجديدة في كل تبويب.</p>\n<p>أعد توليد الحزمة كلها بدل استبدال ملف واحد: تغيير favicon.ico وحده يترك العلامة القديمة على الشاشات الرئيسية وفي البيان، ما يخلق مزيجًا مربكًا من أيقونات قديمة وجديدة. وإذا غيّرت اسم موقعك أو لون السمة، حدّث البيان أيضًا: يكتب المولد بيانًا جديدًا مع كل حزمة، فإعادة التوليد تبقي الاسم والألوان والأيقونات متسقة.</p>\n<p>احتفظ بـZIP القديم حتى تتحقق من أن الحزمة الجديدة حية: إذا كان للرفع الجديد مشكلة، تستعيد الملفات القديمة الأيقونة السابقة في ثوانٍ. وبمجرد تأكيد الأيقونة الجديدة، احذف القديم لتجنب الالتباس.</p>\n<h2 id=\"quick-reference\">مرجع سريع: قائمة تحقق لإنشاء favicon</h2>\n<p>جهّز شعارًا مربعًا بصيغة PNG أو SVG من 512 بكسلًا على الأقل، دون نص صغير. ارفعه إلى المولد واضبط الحشو ونصف قطر الزاوية واختر لون خلفية وراجع المعاينات الفاتحة والداكنة.</p>\n<p>نزّل ZIP وارفع الملفات إلى جذر موقعك والصق المقتطف في قالب head المشترك، واختبر في نافذة خاصة وعلى هاتفك. وامسح ذاكرة التخزين المؤقت إذا استمر الأيقونة القديم في الظهور.</p>\n<p>لمعرفة كل ملف في الحزمة بعمق، اقرأ <a href=\"/ar/blog/dalil-munshi-favicon/\">الدليل الكامل لمولد favicon</a>، وللتفصيل حجمًا بحجم اقرأ <a href=\"/ar/blog/ahjam-favicon-mashruha/\">أحجام favicon موضحة: من 16×16 إلى 512×512</a>. وابدأ الآن من <a href=\"/ar/munshi-favicon/\">مولد favicon</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"أي ملف شعار يجب أن أستخدم لإنشاء favicon؟","answer":"شعار مربع بصيغة PNG أو SVG من 512 بكسلًا على الأقل يعمل أفضل. وSVG مثالي لأنه يتكبر دون فقدان حدة بأي حجم. وJPG يعمل أيضًا، لكنه ليس له شفافية، فـPNG أو SVG يمنحانك خيارات أكثر."},{"question":"لماذا لا يظهر favicon الجديد فورًا؟","answer":"تخزّن المتصفحات favicon في ذاكرة التخزين المؤقت بقوة شديدة، أحيانًا لأسابيع. وقم بتحديث قسري أو افتح URL favicon مباشرة وحدّثه، أو جرّب في نافذة خاصة. وسيظهر الأيقونة الجديد للزوار الجدد فورًا."},{"question":"أين أضع ملفات favicon في موقعي؟","answer":"ارفعها إلى مجلد جذر موقعك، نفس المجلد الذي فيه صفحتك الرئيسية: تبحث المتصفحات عن favicon.ico في الجذر افتراضيًا. ثم الصق مقتطف HTML في قسم head في صفحاتك لربط الأيقونات الأخرى."},{"question":"هل يجب أن أضيف مقتطف HTML إلى كل صفحة؟","answer":"أضفه مرة واحدة إلى قالب head المشترك أو ملف التخطيط الذي تستخدمه كل الصفحات. وفي موقع HTML بسيط يعني ذلك الترويسة المشتركة؛ وفي React أو Next.js يعني ملف التخطيط أو المستند."},{"question":"هل يمكنني إنشاء favicon من صورة على هاتفي؟","answer":"نعم، يقبل المولد صور HEIC من iPhone، إضافة إلى ملفات JPG وPNG. وصورة نادرًا ما تعطي favicon جيدًا عند 16 بكسلًا، فاقص أولًا تفصيلًا بارزًا أو شكلًا قويًا واحدًا لأفضل نتيجة."},{"question":"ماذا يحدث إذا لم يكن شعاري مربعًا؟","answer":"يضبط المولد شعارًا مستطيلًا داخل اللوحة المربعة دون تمديده، لكن النتيجة قد تبدو صغيرة وبمساحة فارغة على الجانبين. ولأفضل نتيجة، جهّز نسخة مربعة من علامتك أو اقص الشعار إلى مربع أولًا."}];
